class TestSlug(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(slugify("Hello World"), "hello-world")
    def test_punct(self):
        self.assertEqual(slugify("Hello,  World!"), "hello-world")
    def test_leading_trailing_and_multiple_hyphens(self):
        self.assertEqual(slugify("--a--b--"), "a-b")
    def test_empty(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify("---"), "")
